const body = $json.body || $json;
const leadId = Number(body.lead_id || 0);
const address = String(body.address || body.property_address || '').trim();
const city = String(body.city || body.property_city || '').trim();
const state = String(body.state || body.property_state || 'NC').trim().toUpperCase();
const zip = String(body.zip || body.property_zip || '').trim();
if (!leadId) throw new Error('lead_id is required');
if (!address || !city || !state) throw new Error('address, city and state are required');
return [{ json: { lead_id: leadId, trace_request: { address, city, state, zip, find_owner: body.find_owner !== false }, requested_at: new Date().toISOString() } }];

const trace = $json;
const persons = Array.isArray(trace.persons) ? trace.persons : [];
const person = persons[0] || {};
const phones = Array.isArray(person.phones) ? person.phones : [];
const emails = Array.isArray(person.emails) ? person.emails : [];
const primaryPhone = phones.find(p => !p.dnc && !p.litigator) || phones[0] || null;
const blockedPhone = phones.some(p => Boolean(p.dnc || p.litigator || p.tcpa));
return [{ json: { trace, lead_id: $('Normalize Trace Request').first().json.lead_id, hit: Boolean(trace.hit), owner: { first_name: person.first_name || null, last_name: person.last_name || null }, primary_phone: primaryPhone?.number || null, primary_phone_flags: primaryPhone ? { dnc: Boolean(primaryPhone.dnc), litigator: Boolean(primaryPhone.litigator), tcpa: Boolean(primaryPhone.tcpa), type: primaryPhone.type || null, carrier: primaryPhone.carrier || null } : null, primary_email: emails[0]?.email || null, do_not_contact: blockedPhone, phones_found: phones.length, emails_found: emails.length, credits_deducted: trace.credits_deducted || 0, trace_request_id: trace.meta?.request_id || null } }];
